using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
// The default Web options include a reflection-based resolver, so
// GetTypeInfo<T> returns a JsonTypeInfo<T> directly — no cast needed.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---
// With a resolver that only knows about Person, probing for an
// unregistered type returns false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// Make the options immutable so the resolver is locked in.
limited.MakeReadOnly();

if (limited.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? pInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person>() → found: {pInfo!.Type.Name}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo<Person>() → not found");
}

// Now try a type the resolver can handle but wrap it in a custom resolver
// that deliberately returns null to simulate "not available".
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()
};
empty.MakeReadOnly();

if (empty.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person>() → found (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person>() with NullResolver → not found (no exception!)");
}

// --- Types ---
public record Person(string Name, int Age);

/// A resolver that never resolves anything — used to demonstrate
/// TryGetTypeInfo returning false.
file sealed class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

